text:
& .config-detail {
  gap: var(--hub-space-medium);

  .config-protocols & {
    padding-block: 0;
  }

  & .config-item-data {
    overflow: hidden;
    display: flex;
    flex-direction: column;
    align-items: baseline;
    gap: 2px;

    & p {
      line-height: normal;
      margin: 0;

      &.title {
        text-transform: uppercase;
        color: var(--color-text-secondary);
        font-weight: 500;
        font-size: 0.8rem;
        display: inline-block;
        vertical-align: bottom;
      }

      &.data {
        color: var(--color-text-base);
        font-weight: 400;
        font-size: 1rem;
        text-wrap: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
      }
